// One import point for the Convex API and the shapes the screens use.
// Screens import from "@/lib/convex" instead of reaching into ../../convex/_generated by hand.
import type { FunctionReturnType } from "convex/server";
import { api } from "../../convex/_generated/api";

export type { Doc, Id } from "../../convex/_generated/dataModel";
export { api };

export type Snapshot = NonNullable<
	FunctionReturnType<typeof api.views.getSessionSnapshot>
>;
export type RouteView = NonNullable<
	FunctionReturnType<typeof api.views.getRouteForSession>
>;
export type FleetView = FunctionReturnType<typeof api.views.getFleetOverview>;
export type FeedEvent = FunctionReturnType<
	typeof api.views.getSessionFeed
>[number];
export type SessionRef = FunctionReturnType<
	typeof api.views.listSessionIds
>[number];
export type RecentSession = FunctionReturnType<
	typeof api.views.listRecentSessions
>[number];
